const x=c.getContext('2d'),N=29;x.fillStyle='#fff';x.fillRect(0,0,N,N);x.fillStyle='#0a2a8a';let q=tpA*7919+13;const r=()=>(q=(q*16807)%2147483647)/2147483647;
