function aaBalUpd(){const b=AU.bs,v=b.amt,bal=+AU.p.balance,nb=bal+b.sg*v,ok=v>0&&v<=1e9&&nb>=0,t=$('#aabt'),pv=$('#aapv'),g=$('#aabg');t.textContent=b.sg>0?'เพิ่มเงินให้บัญชี':'หักเงินจากบัญชี';tr(t);
document.querySelectorAll('#aasg button').forEach(x=>x.classList.toggle('on',+x.dataset.sg===b.sg));document.querySelectorAll('[data-aq]').forEach(c=>c.classList.toggle('on',+c.dataset.aq===v));
pv.className='aa-pv'+(v&&!ok?' err':'');pv.textContent=!v?'ใส่จำนวนเงินที่ต้องการ':v>1e9?'จำนวนมากเกินไป':nb<0?'ยอดเงินไม่พอให้หัก ('+tpf(bal)+' กีบ)':'ยอดหลังปรับ '+tpf(nb)+' กีบ';tr(pv);g.disabled=!ok;g.classList.toggle('aa-red',b.sg<0)}
async function aaBalGo(){const b=AU.bs,g=$('#aabg'),rs=$('#aars').value.trim();if(!confirm(trs((b.sg>0?'เพิ่มเงิน ':'หักเงิน ')+tpf(b.amt)+' กีบ '+(b.sg>0?'ให้บัญชี ':'จากบัญชี ')+AU.p.username+' ใช่ไหม?')))return;g.disabled=true;
try{await aaRpc('admin_adjust_balance',{p_user:AU.p.id,p_amount:b.sg*b.amt,p_reason:rs||null});await aaDone(b.sg>0?'เพิ่มเงินสำเร็จ':'หักเงินสำเร็จ')}catch(x){g.disabled=false;tpToast(aaM(x))}} // ADMIN
