function aaBanH(){const b=AU.bn;if(b.h===0)return null;if(b.h>0)return b.h;const n=parseFloat(($('#aacn').value||'').replace(',','.')),u=$('#aacnu').value;if(!(n>0))return NaN;return u==='m'?n/60:u==='d'?n*24:n}
function aaBanUpd(){const b=AU.bn,h=aaBanH(),ok=h===null||(h>0&&h<=87600),pv=$('#aapv'),g=$('#aabg');$('#aacu').hidden=b.h!==-1;document.querySelectorAll('[data-ah]').forEach(c=>c.classList.toggle('on',+c.dataset.ah===b.h));
pv.className='aa-pv'+(ok?'':' err');pv.textContent=h===null?'แบนถาวร ไม่มีวันหมดอายุ':ok?'จะถูกแบนถึง '+aaDt(Date.now()+h*36e5)+(aaBanned(AU.p)?' · แทนที่การแบนเดิม':''):'ระบุระยะเวลาให้ถูกต้อง';tr(pv);g.disabled=!ok}
async function aaBanGo(){const h=aaBanH(),g=$('#aabg'),rs=$('#aars').value.trim();if(!confirm(trs('แบน '+AU.p.username+' '+(h===null?'ถาวร':'นาน '+(h<1?Math.round(h*60)+' นาที':h<48?+h.toFixed(2)+' ชั่วโมง':+(h/24).toFixed(2)+' วัน'))+' ใช่ไหม?')))return;g.disabled=true;
try{await aaRpc('admin_ban_user',{p_user:AU.p.id,p_hours:h,p_reason:rs||null});await aaDone('แบนบัญชีแล้ว')}catch(x){g.disabled=false;tpToast(aaM(x))}} // ADMIN
