async function aaRole(){const to=AU.p.role==='admin'?'user':'admin';if(!confirm(trs(to==='admin'?'ตั้ง '+AU.p.username+' ให้เป็นแอดมิน? แอดมินจัดการเงินและบัญชีทุกคนได้':'ถอดสิทธิ์แอดมินของ '+AU.p.username+' ใช่ไหม?')))return;try{await aaRpc('admin_set_role',{p_user:AU.p.id,p_role:to});await aaDone('เปลี่ยนสิทธิ์แล้ว')}catch(x){tpToast(aaM(x))}} // ADMIN
